-- Valve's open-source GameNetworkingSockets, statically linked for direct-IP connections: reliable and unreliable messages over UDP with
-- encryption, fragmentation, congestion control, and simulated network conditions for tests. P2P, ICE, and WebRTC stay off, so its Abseil and
-- WebRTC submodules are never needed. Windows signs and encrypts with BCrypt and the bundled 25519 reference code; Linux uses the system's
-- OpenSSL libcrypto. Its wire messages are Protobuf, generated by the protoc built from External/protobuf.
function HertaGameNetworkingSockets()
    local RepositoryRoot = path.getabsolute(_MAIN_SCRIPT_DIR)
    local Root = path.join(RepositoryRoot, "External/GameNetworkingSockets/src")
    local ProjectFilesRoot = path.join(RepositoryRoot, "Intermediate/ProjectFiles", (_ACTION or "NoAction") .. HertaToolsetSuffix)
    local Generated = path.join(RepositoryRoot, "Intermediate/Generated" .. HertaToolsetSuffix .. "/GameNetworkingSockets")
    local BinaryRoot = path.join(RepositoryRoot, "Binaries/%{cfg.system}/%{cfg.architecture}/%{cfg.buildcfg}" .. HertaToolsetSuffix)

    local Sources = {
        "common/steamid.cpp",
        "steamnetworkingsockets/steamnetworkingsockets_certs.cpp",
        "steamnetworkingsockets/steamnetworkingsockets_certstore.cpp",
        "steamnetworkingsockets/steamnetworkingsockets_shared.cpp",
        "tier0/dbg.cpp",
        "tier0/platformtime.cpp",
        "tier0/valve_tracelogging.cpp",
        "tier1/netadr.cpp",
        "tier1/utlbuffer.cpp",
        "tier1/utlmemory.cpp",
        "tier1/ipv6text.c",
        "vstdlib/strtools.cpp",
        "steamnetworkingsockets/steamnetworkingsockets_stats.cpp",
        "steamnetworkingsockets/steamnetworkingsockets_thinker.cpp",
        "steamnetworkingsockets/clientlib/csteamnetworkingsockets.cpp",
        "steamnetworkingsockets/clientlib/csteamnetworkingmessages.cpp",
        "steamnetworkingsockets/clientlib/steamnetworkingsockets_flat.cpp",
        "steamnetworkingsockets/clientlib/steamnetworkingsockets_connections.cpp",
        "steamnetworkingsockets/clientlib/steamnetworkingsockets_socketthread.cpp",
        "steamnetworkingsockets/clientlib/steamnetworkingsockets_lowlevel_misc.cpp",
        "steamnetworkingsockets/clientlib/steamnetworkingsockets_spew.cpp",
        "steamnetworkingsockets/clientlib/steamnetworkingsockets_taskqueue.cpp",
        "steamnetworkingsockets/clientlib/steamnetworkingsockets_ice_client.cpp",
        "steamnetworkingsockets/clientlib/steamnetworkingsockets_p2p.cpp",
        "steamnetworkingsockets/clientlib/steamnetworkingsockets_p2p_ice.cpp",
        "steamnetworkingsockets/clientlib/steamnetworkingsockets_p2p_webrtc.cpp",
        "steamnetworkingsockets/clientlib/steamnetworkingsockets_snp.cpp",
        "steamnetworkingsockets/clientlib/steamnetworkingsockets_udp.cpp",
        "common/crypto.cpp",
        "common/crypto_textencode.cpp",
        "common/keypair.cpp",
    }

    local Protos = {
        "common/steamnetworkingsockets_messages_certs.proto",
        "common/steamnetworkingsockets_messages.proto",
        "common/steamnetworkingsockets_messages_udp.proto",
    }

    project "GameNetworkingSockets"
        kind "StaticLib"
        location(path.join(ProjectFilesRoot, "GameNetworkingSockets"))
        targetdir(BinaryRoot)
        objdir(path.join(RepositoryRoot, "Intermediate/Build/%{cfg.system}/%{cfg.architecture}/%{cfg.buildcfg}" .. HertaToolsetSuffix .. "/%{prj.name}"))
        language "C++"
        cppdialect "C++17"
        warnings "Off"
        dependson { "Protoc" }

        for _, Source in ipairs(Sources) do
            files { path.join(Root, Source) }
        end

        for _, Proto in ipairs(Protos) do
            files { path.join(Root, Proto) }
        end

        externalincludedirs {
            path.join(RepositoryRoot, "External/GameNetworkingSockets/include"),
            path.join(Root, "common"),
            path.join(Root, "public"),
            path.join(RepositoryRoot, "External/protobuf/src"),
            Generated,
        }

        defines { "STEAMNETWORKINGSOCKETS_STATIC_LINK", "STEAMNETWORKINGSOCKETS_FOREXPORT", "GOOGLE_PROTOBUF_NO_RTTI", "ENABLE_OPENSSLCONNECTION", "VALVE_CRYPTO_ENABLE_25519" }

        -- protoc runs before the library compiles, writing each message file's code where only this build reads it.
        filter "files:**.proto"
            buildmessage "Generating %{file.basename}.pb.cc"
            buildoutputs { path.join(Generated, "%{file.basename}.pb.cc"), path.join(Generated, "%{file.basename}.pb.h") }
            compilebuildoutputs "On"

        filter { "files:**.proto", "system:windows" }
            buildcommands {
                'if not exist "' .. path.translate(Generated) .. '" mkdir "' .. path.translate(Generated) .. '"',
                '"' .. path.translate(path.join(BinaryRoot, "Protoc.exe")) .. '" --cpp_out="' .. path.translate(Generated) .. '" -I"' .. path.translate(path.join(Root, "common")) .. '" "%{file.abspath}"',
            }

        filter { "files:**.proto", "system:linux" }
            buildcommands {
                'mkdir -p "' .. Generated .. '"',
                '"' .. path.join(BinaryRoot, "Protoc") .. '" --cpp_out="' .. Generated .. '" -I"' .. path.join(Root, "common") .. '" "%{file.abspath}"',
            }

        -- Its headers insist on exactly one of these on MSVC; the debug runtime already defines _DEBUG.
        filter "configurations:Development or Shipping"
            defines { "NDEBUG" }

        filter "system:windows"
            -- It times its socket thread with winmm, which the lean Windows headers leave out.
            undefines { "WIN32_LEAN_AND_MEAN" }
            defines { "_CRT_SECURE_NO_WARNINGS", "_CRT_NONSTDC_NO_WARNINGS", "_WINDOWS", "VALVE_CRYPTO_BCRYPT", "VALVE_CRYPTO_25519_DONNA", "ED25519_HASH_BCRYPT" }
            files {
                path.join(Root, "common/crypto_bcrypt.cpp"),
                path.join(Root, "common/crypto_25519_donna.cpp"),
                path.join(Root, "external/curve25519-donna/curve25519.c"),
                path.join(Root, "external/curve25519-donna/curve25519_VALVE_sse2.c"),
                path.join(Root, "external/ed25519-donna/ed25519_VALVE.c"),
                path.join(Root, "external/ed25519-donna/ed25519_VALVE_sse2.c"),
            }
            buildoptions { "/bigobj" }

        filter "system:linux"
            -- Its assertion macros drop a trailing comma with GNU's ", ## __VA_ARGS__", which strict C++17 keeps.
            cppdialect "gnu++17"
            defines { "LINUX", "VALVE_CRYPTO_OPENSSL", "VALVE_CRYPTO_25519_OPENSSLEVP" }
            files {
                path.join(Root, "common/crypto_openssl.cpp"),
                path.join(Root, "common/crypto_25519_openssl.cpp"),
                path.join(Root, "common/crypto_digest_opensslevp.cpp"),
                path.join(Root, "common/crypto_symmetric_opensslevp.cpp"),
                path.join(Root, "common/opensslwrapper.cpp"),
            }
            buildoptions { "-fno-strict-aliasing" }

        filter {}
end
